<form class="o-menu-date" method="get"><input type="hidden" name="slot_id" value="<?= e($slotId) ?>"><label>Menu date <input class="o-input" type="date" name="date" value="<?= e($date) ?>" required></label><button class="o-btn">View menu</button><nav class="o-menu-date-options"><?php foreach([date('Y-m-d')=>'Today',date('Y-m-d',strtotime('+1 day'))=>'Tomorrow'] as $d=>$label):?><a class="o-btn <?= $date===$d?'is-selected':'' ?>" href="?slot_id=<?= e($slotId) ?>&date=<?= e($d) ?>"><?= e($label) ?></a><?php endforeach;?></nav></form>
